#!/usr/bin/env node
/**
 * `npm run gen:untitled-icons`
 *
 * Reads the pinned `@untitledui/icons` package and writes
 * `src/generated/untitled-icons.ts` — name + path data for the local browser.
 *
 * The generated file is gitignored: Untitled UI's license allows using the
 * icons in products, not redistributing the glyph set. The npm package is the
 * source of truth; this script is the only way the glyphs enter the app.
 *
 * Skip regeneration when the output already matches the installed version.
 */

import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const outDir = join(root, 'src/generated')
const outFile = join(outDir, 'untitled-icons.ts')

const pkgDir = join(root, 'node_modules/@untitledui/icons')
const pkgPath = join(pkgDir, 'package.json')
if (!existsSync(pkgPath)) {
  throw new Error('Install @untitledui/icons first: npm i -D @untitledui/icons')
}
const pkg = JSON.parse(readFileSync(pkgPath, 'utf8'))
const distDir = join(pkgDir, 'dist')

if (existsSync(outFile)) {
  const prev = readFileSync(outFile, 'utf8')
  const ver = /UNTITLED_ICONS_VERSION = ["']([^"']+)["']/.exec(prev)?.[1]
  const count = /UNTITLED_ICONS_COUNT = (\d+)/.exec(prev)?.[1]
  if (ver === pkg.version && count && Number(count) > 1000) {
    console.log(`untitled-icons catalog up to date (${pkg.version}, ${count} icons)`)
    process.exit(0)
  }
}

function toSlug(name) {
  return name
    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1-$2')
    .replace(/([A-Za-z])(\d)/g, '$1-$2')
    .toLowerCase()
}

function parseProps(raw) {
  const d = /(?:^|,)d:"((?:\\.|[^"\\])*)"/.exec(raw)?.[1]
  if (!d) return null
  const clipRule = /clipRule:"([^"]+)"/.exec(raw)?.[1]
  return clipRule ? { d, clipRule } : { d }
}

function parseModule(src, file) {
  const name = /displayName="([^"]+)"/.exec(src)?.[1]
  if (!name) throw new Error(`no displayName in ${file}`)
  const paths = []
  const re = /createElement\("path",\{([^}]+)\}\)/g
  let m
  while ((m = re.exec(src))) {
    const parsed = parseProps(m[1])
    if (parsed) paths.push(parsed)
  }
  if (paths.length === 0) throw new Error(`no paths in ${file}`)
  return { name, slug: toSlug(name), paths }
}

const files = readdirSync(distDir).filter((f) => f.endsWith('.mjs') && f !== 'index.mjs')
const icons = files
  .map((file) => parseModule(readFileSync(join(distDir, file), 'utf8'), file))
  .sort((a, b) => a.name.localeCompare(b.name))

if (icons.length < 1000) {
  throw new Error(`expected 1,100+ Untitled UI icons, got ${icons.length}`)
}

mkdirSync(outDir, { recursive: true })
writeFileSync(
  outFile,
  `/* Generated by scripts/fetch-untitled-icons.mjs from ${pkg.name}@${pkg.version}. Do not edit. */
export const UNTITLED_ICONS_PACKAGE = ${JSON.stringify(pkg.name)}
export const UNTITLED_ICONS_VERSION = ${JSON.stringify(pkg.version)}
export const UNTITLED_ICONS_COUNT = ${icons.length}
export const UNTITLED_ICONS = ${JSON.stringify(icons)}
`,
)

console.log(`wrote ${icons.length} icons from ${pkg.name}@${pkg.version} → src/generated/untitled-icons.ts`)
